#### Phase 1: Extension Component Structure (Week 1-2)

**Step 1: Define Props Interface**
Create TypeScript interface extending ExtensionComponentProps from SDK. Include extension-specific props.

```typescript
// src/types/ClaimsValidatorProps.ts
import { ExtensionComponentProps } from '@gainwell/extensions-sdk-react';

export interface ClaimsValidatorProps extends ExtensionComponentProps {
  claimId: string;              // Required: Claim to validate
  validationRules: string[];    // Optional: Custom rules
  onValidationComplete: (result: ValidationResult) => void;
}

export interface ValidationResult {
  isValid: boolean;
  errors: ValidationError[];
  warnings: string[];
}
```

**Step 2: Implement Component with Hooks**
Create functional component using React hooks (useState, useEffect, useMemo). Integrate design system components.

```typescript
// src/components/ClaimsValidator.tsx
import React, { useState, useEffect, useMemo } from 'react';
import { Button, Card, Alert, Spinner } from '@gainwell/design-system-react';
import { ClaimsValidatorProps, ValidationResult } from '../types';
import { validateClaim } from '../services/validation';

export const ClaimsValidator: React.FC<ClaimsValidatorProps> = ({
  claimId,
  validationRules = [],
  onValidationComplete,
  context  // From ExtensionComponentProps
}) => {
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState<ValidationResult | null>(null);

  const { tenantId, userId } = context;

  const handleValidate = async () => {
    setLoading(true);
    try {
      const validationResult = await validateClaim(claimId, validationRules, tenantId);
      setResult(validationResult);
      onValidationComplete(validationResult);
    } catch (error) {
      console.error('Validation failed:', error);
      // Error boundary will catch unhandled errors
    } finally {
      setLoading(false);
    }
  };

  // Memoize expensive computation
  const errorSummary = useMemo(() => {
    if (!result) return null;
    return result.errors.reduce((acc, err) => acc + err.severity, 0);
  }, [result]);

  return (
    <Card title="Claims Validator" data-testid="claims-validator">
      <Button
        onClick={handleValidate}
        disabled={loading}
        aria-label="Validate claim"
      >
        {loading ? <Spinner size="small" /> : 'Validate Claim'}
      </Button>

      {result && (
        <Alert
          type={result.isValid ? 'success' : 'error'}
          message={result.isValid ? 'Claim is valid' : `${result.errors.length} errors found`}
        />
      )}
    </Card>
  );
};

// Named export for testing
export default ClaimsValidator;
```

**Step 3: Add Error Boundary**
Wrap component in ExtensionErrorBoundary to isolate failures.

```typescript
// src/components/ClaimsValidatorSafe.tsx
import React from 'react';
import { ExtensionErrorBoundary } from '@gainwell/extensions-sdk-react';
import ClaimsValidator from './ClaimsValidator';
import { ClaimsValidatorProps } from '../types';

export const ClaimsValidatorSafe: React.FC<ClaimsValidatorProps> = (props) => (
  <ExtensionErrorBoundary
    fallback={
      <div role="alert" style={{ padding: '1rem', border: '1px solid red' }}>
        <h3>Claims Validator failed to load</h3>
        <p>Please contact support if this issue persists.</p>
      </div>
    }
    onError={(error, errorInfo) => {
      console.error('Extension error:', error, errorInfo);
      // Send to telemetry (Application Insights, Datadog, etc.)
      window.appInsights?.trackException({ exception: error, properties: { component: 'ClaimsValidator' } });
    }}
  >
    <ClaimsValidator {...props} />
  </ExtensionErrorBoundary>
);

export default ClaimsValidatorSafe;
```

**Step 4: Configure Styling Isolation**
Use design system styling; avoid global CSS. If custom styles needed, use CSS-in-JS.

```typescript
// src/components/ClaimsValidator.tsx (styled-components variant)
import styled from 'styled-components';
import { Card } from '@gainwell/design-system-react';

const StyledCard = styled(Card)`
  /* Scoped styles - won't leak to host */
  .validator-summary {
    background: ${props => props.theme.colors.background};
    padding: 1rem;
  }
`;

export const ClaimsValidator = (props) => (
  <StyledCard title="Claims Validator">
    {/* Component content */}
  </StyledCard>
);
```

