#### Phase 2: Integration and Testing (Week 3-4)

**Step 1: Register Component with Extension Registry**
Create entry point file exporting component and metadata.

```typescript
// src/index.tsx
import { ExtensionManifest } from '@gainwell/extensions-sdk-react';
import ClaimsValidatorSafe from './components/ClaimsValidatorSafe';
import { ClaimsValidatorProps } from './types';

export const manifest: ExtensionManifest = {
  extensionId: 'texas-claims-validator-v1',
  extensionPoint: 'claims-detail-panel',  // From PTN-APP-EXT-002 spec
  component: ClaimsValidatorSafe,
  propsSchema: {  // JSON Schema for validation
    type: 'object',
    required: ['claimId', 'onValidationComplete'],
    properties: {
      claimId: { type: 'string' },
      validationRules: { type: 'array', items: { type: 'string' } },
      onValidationComplete: { type: 'function' }
    }
  },
  metadata: {
    name: 'Texas Claims Validator',
    version: '1.0.0',
    author: 'Texas HHSC',
    description: 'Custom validation rules for Texas Medicaid claims'
  }
};

export { ClaimsValidatorSafe as Component };
export type { ClaimsValidatorProps };
```

**Step 2: Test Component in Isolation**
Unit tests with Jest + React Testing Library.

```typescript
// src/components/__tests__/ClaimsValidator.test.tsx
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import '@testing-library/jest-dom';
import ClaimsValidator from '../ClaimsValidator';
import { validateClaim } from '../../services/validation';

jest.mock('../../services/validation');

describe('ClaimsValidator', () => {
  const mockContext = {
    tenantId: 'texas-hhsc',
    userId: 'user123',
    permissions: ['claims:validate']
  };

  const mockOnComplete = jest.fn();

  beforeEach(() => {
    jest.clearAllMocks();
  });

  it('renders validation button', () => {
    render(
      <ClaimsValidator
        claimId="CLM-12345"
        onValidationComplete={mockOnComplete}
        context={mockContext}
      />
    );

    expect(screen.getByRole('button', { name: /validate claim/i })).toBeInTheDocument();
  });

  it('displays validation result on success', async () => {
    (validateClaim as jest.Mock).mockResolvedValue({
      isValid: true,
      errors: [],
      warnings: []
    });

    render(
      <ClaimsValidator
        claimId="CLM-12345"
        onValidationComplete={mockOnComplete}
        context={mockContext}
      />
    );

    fireEvent.click(screen.getByRole('button', { name: /validate claim/i }));

    await waitFor(() => {
      expect(screen.getByText(/claim is valid/i)).toBeInTheDocument();
    });

    expect(mockOnComplete).toHaveBeenCalledWith(
      expect.objectContaining({ isValid: true })
    );
  });

  it('handles validation errors gracefully', async () => {
    (validateClaim as jest.Mock).mockRejectedValue(new Error('Network error'));

    render(
      <ClaimsValidator
        claimId="CLM-12345"
        onValidationComplete={mockOnComplete}
        context={mockContext}
      />
    );

    fireEvent.click(screen.getByRole('button', { name: /validate claim/i }));

    // Error boundary should prevent crash
    await waitFor(() => {
      expect(screen.queryByText(/network error/i)).not.toBeInTheDocument();
    });
  });
});
```

**Step 3: Test Integration with Host Application**
Integration tests in host app environment.

```typescript
// integration-tests/ClaimsValidatorIntegration.test.tsx
import { render, screen } from '@testing-library/react';
import { Provider } from 'react-redux';
import { ExtensionSlot } from '@gainwell/extensions-sdk-react';
import { store } from '../store';  // Host app Redux store
import { manifest } from 'texas-claims-validator';

describe('ClaimsValidator Integration', () => {
  it('loads extension in host app', () => {
    // Register extension
    ExtensionRegistry.register(manifest);

    // Render extension point in host app
    render(
      <Provider store={store}>
        <ExtensionSlot
          extensionPoint="claims-detail-panel"
          claimId="CLM-12345"
          onValidationComplete={(result) => console.log(result)}
        />
      </Provider>
    );

    expect(screen.getByTestId('claims-validator')).toBeInTheDocument();
  });
});
```

**Step 4: Validate Accessibility Compliance**
Automated + manual testing.

```typescript
// src/components/__tests__/ClaimsValidator.a11y.test.tsx
import { render } from '@testing-library/react';
import { axe, toHaveNoViolations } from 'jest-axe';
import ClaimsValidator from '../ClaimsValidator';

expect.extend(toHaveNoViolations);

describe('ClaimsValidator Accessibility', () => {
  it('has no automated accessibility violations', async () => {
    const { container } = render(
      <ClaimsValidator
        claimId="CLM-12345"
        onValidationComplete={() => {}}
        context={{ tenantId: 'texas', userId: 'user1', permissions: [] }}
      />
    );

    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });
});
```

